import torch

def run(grad_output, self_input, padding):
    return torch.ops.aten.reflection_pad3d_backward(grad_output, self_input, padding)

def _dtype_from_context(ctx, name):
    return getattr(torch, ctx[f"{name}__dtype"])

def gen_inputs(ctx, device):
    return {
        "grad_output": torch.ones(
            ctx["grad_output__shape"],
            dtype=_dtype_from_context(ctx, "grad_output"),
            device=device,
        )
    }
